#include <cstdint>
#include <iostream>

static const uint32_t kMaskDelta = 0xa282ead8ul;

// Mask function
inline uint32_t Mask(uint32_t crc) {
    // Rotate right by 15 bits, then add delta
    uint32_t rotated = (crc >> 15) | (crc << 17);
    return rotated + kMaskDelta;
}

// Unmask function (to be implemented)
uint32_t crc32c_Unmask(uint32_t masked_crc) {
    uint32_t rot = masked_crc - kMaskDelta;
    return (rot >> 17) | (rot << 15);
}

int main() {
    // Test roundtrip: mask then unmask should give original value
    uint32_t test_values[] = {0, 1, 0xFFFFFFFF, 0x12345678, 0xDEADBEEF, 0xA5A5A5A5};

    for (uint32_t val : test_values) {
        uint32_t masked = Mask(val);
        uint32_t unmasked = crc32c_Unmask(masked);
        std::cout << "Original: 0x" << std::hex << val 
                  << " -> Masked: 0x" << masked 
                  << " -> Unmasked: 0x" << unmasked 
                  << " -> Match: " << (unmasked == val ? "YES" : "NO") 
                  << std::endl;
    }

    return 0;
}

